-- ============================================================
-- นำเข้าคำถามสาขาไฟฟ้า หมวดที่ 14: ระบบแสงสว่าง (Lighting Design)
-- ไฟล์นี้รันได้อิสระ ไม่ต้องพึ่งไฟล์อื่น (idempotent)
-- ============================================================

begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'lighting', 'ระบบแสงสว่าง (Lighting Design)', 14
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'lighting'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'หน่วยวัดทางโฟโตเมตริก (Photometric Unit) ที่สำคัญ ได้แก่ ลูเมน (Lumen) ลักซ์ (Lux) และแคนเดลา (Candela) มีความหมายและความสัมพันธ์กันอย่างไร', 'ลูเมนคือหน่วยวัดปริมาณแสงทั้งหมดที่แหล่งกำเนิดแสงปล่อยออกมา แคนเดลาคือหน่วยวัดความเข้มของแสงในทิศทางใดทิศทางหนึ่งโดยเฉพาะ ส่วนลักซ์คือหน่วยวัดความส่องสว่างที่ตกกระทบบนพื้นผิว ซึ่งเท่ากับปริมาณลูเมนต่อหนึ่งตารางเมตรของพื้นที่ที่ได้รับแสงนั้น', 'การเข้าใจความสัมพันธ์ของหน่วยเหล่านี้เป็นพื้นฐานสำคัญในการออกแบบระบบแสงสว่าง เนื่องจากผู้ออกแบบมักเริ่มจากการกำหนดค่าความส่องสว่างที่ต้องการ (ลักซ์) บนพื้นที่ทำงาน แล้วคำนวณย้อนกลับเป็นปริมาณลูเมนของหลอดไฟที่ต้องใช้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'หน่วยวัดทางโฟโตเมตริก (Photometric Unit) ที่สำคัญ ได้แก่ ลูเมน (Lumen) ลักซ์ (Lux) และแคนเดลา (Candela) มีความหมายและความสัมพันธ์กันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ประสิทธิภาพการส่องสว่าง (Luminous Efficacy) ของแหล่งกำเนิดแสงคืออะไร และมีหน่วยวัดอย่างไร', 'คืออัตราส่วนระหว่างปริมาณแสงที่ผลิตได้ (ลูเมน) ต่อกำลังไฟฟ้าที่ใช้ (วัตต์) มีหน่วยเป็นลูเมนต่อวัตต์ (lm/W) ค่านี้บ่งบอกถึงประสิทธิภาพในการเปลี่ยนพลังงานไฟฟ้าเป็นแสงสว่างของแหล่งกำเนิดแสงแต่ละชนิด', 'การเปรียบเทียบประสิทธิภาพการส่องสว่างระหว่างเทคโนโลยีหลอดไฟต่างชนิดเป็นปัจจัยสำคัญในการเลือกใช้หลอดไฟที่ประหยัดพลังงาน โดยหลอด LED มักมีค่าประสิทธิภาพการส่องสว่างสูงกว่าหลอดไส้และหลอดฟลูออเรสเซนต์อย่างมีนัยสำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ประสิทธิภาพการส่องสว่าง (Luminous Efficacy) ของแหล่งกำเนิดแสงคืออะไร และมีหน่วยวัดอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อุณหภูมิสี (Color Temperature) ของแสงมีความหมายอย่างไร และเหตุใดจึงมีผลต่อบรรยากาศของพื้นที่ที่ใช้งาน', 'คือค่าที่บ่งบอกโทนสีของแสงเทียบกับสีของวัตถุดำที่ถูกเผาจนร้อนถึงอุณหภูมิหนึ่ง มีหน่วยเป็นเคลวิน (K) แสงที่มีอุณหภูมิสีต่ำจะให้โทนสีอุ่น (เหลืองส้ม) ในขณะที่แสงที่มีอุณหภูมิสีสูงจะให้โทนสีเย็น (ขาวฟ้า) ซึ่งส่งผลต่อความรู้สึกและบรรยากาศของพื้นที่นั้นแตกต่างกัน', 'การเลือกอุณหภูมิสีที่เหมาะสมขึ้นอยู่กับลักษณะการใช้งาน เช่น พื้นที่พักผ่อนมักเลือกโทนสีอุ่นเพื่อความรู้สึกผ่อนคลาย ในขณะที่พื้นที่ทำงานหรือโรงงานมักเลือกโทนสีเย็นเพื่อกระตุ้นความตื่นตัวและช่วยให้มองเห็นรายละเอียดชัดเจน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อุณหภูมิสี (Color Temperature) ของแสงมีความหมายอย่างไร และเหตุใดจึงมีผลต่อบรรยากาศของพื้นที่ที่ใช้งาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ดัชนีความถูกต้องของสี (Color Rendering Index, CRI) คืออะไร และมีความสำคัญอย่างไรในการเลือกใช้แหล่งกำเนิดแสง', 'เป็นค่าที่บ่งบอกความสามารถของแหล่งกำเนิดแสงในการแสดงสีของวัตถุให้ใกล้เคียงกับที่เห็นภายใต้แสงธรรมชาติมากเพียงใด มีค่าสูงสุดที่ 100 ยิ่งค่าสูงยิ่งแสดงสีได้ถูกต้องใกล้เคียงความเป็นจริงมากขึ้น', 'งานที่ต้องการความแม่นยำด้านสีสูง เช่น ร้านขายเสื้อผ้าหรือห้องตรวจสอบคุณภาพสินค้า จำเป็นต้องเลือกใช้แหล่งกำเนิดแสงที่มีค่า CRI สูง ในขณะที่พื้นที่ทั่วไป เช่น ทางเดินหรือลานจอดรถ อาจไม่จำเป็นต้องเน้นค่า CRI สูงมากเท่างานที่ต้องการความแม่นยำด้านสี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ดัชนีความถูกต้องของสี (Color Rendering Index, CRI) คืออะไร และมีความสำคัญอย่างไรในการเลือกใช้แหล่งกำเนิดแสง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แสงจ้าบาดตา (Glare) ในระบบแสงสว่างคืออะไร และมีผลกระทบต่อผู้ใช้งานอย่างไร', 'คือความรู้สึกไม่สบายตาหรือมองเห็นได้ลำบาก ที่เกิดจากความสว่างที่มากเกินไปหรือความแตกต่างของความสว่างที่สูงเกินไปในสายตา ซึ่งอาจเกิดจากการมองแหล่งกำเนิดแสงโดยตรงหรือแสงสะท้อนจากพื้นผิว ผลกระทบรวมถึงความเมื่อยล้าทางสายตา ลดประสิทธิภาพการมองเห็น และในบางกรณีอาจเป็นอันตราย เช่น แสงจ้าที่รบกวนการมองเห็นขณะขับรถ', 'การออกแบบระบบแสงสว่างที่ดีต้องพิจารณาควบคุมแสงจ้าบาดตาด้วยวิธีต่างๆ เช่น การเลือกโคมไฟที่มีแผ่นกระจายแสงหรือแผ่นบังแสงที่เหมาะสม และการจัดวางตำแหน่งโคมไฟให้ไม่อยู่ในแนวสายตาโดยตรงของผู้ใช้งาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แสงจ้าบาดตา (Glare) ในระบบแสงสว่างคืออะไร และมีผลกระทบต่อผู้ใช้งานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ดัชนีแสงจ้ารวม (Unified Glare Rating, UGR) ใช้ประเมินความรุนแรงของแสงจ้าบาดตาในพื้นที่ทำงานอย่างไร', 'เป็นค่าที่คำนวณจากความสว่างของโคมไฟแต่ละดวงในพื้นที่ ตำแหน่งของโคมไฟเทียบกับตำแหน่งการมองของผู้สังเกต และความสว่างพื้นหลังของพื้นที่โดยรวม ค่า UGR ที่ต่ำแสดงว่าพื้นที่นั้นมีความเสี่ยงจากแสงจ้าบาดตาต่ำกว่า', 'มาตรฐานการออกแบบแสงสว่างมักกำหนดค่า UGR สูงสุดที่ยอมรับได้แตกต่างกันตามลักษณะงาน เช่น งานที่ต้องใช้สายตาละเอียดหรืองานที่ต้องจ้องมองหน้าจอคอมพิวเตอร์เป็นเวลานาน มักต้องการค่า UGR ที่ต่ำกว่างานทั่วไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ดัชนีแสงจ้ารวม (Unified Glare Rating, UGR) ใช้ประเมินความรุนแรงของแสงจ้าบาดตาในพื้นที่ทำงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วิธีคำนวณแสงสว่างแบบ Lumen Method (หรือ Zonal Cavity Method) ใช้หลักการพื้นฐานอย่างไรในการหาจำนวนโคมไฟที่ต้องติดตั้ง', 'คำนวณจากค่าความส่องสว่างเป้าหมายที่ต้องการ พื้นที่ของห้อง ปริมาณลูเมนต่อโคมไฟ และตัวประกอบการใช้ประโยชน์ (Utilization Factor) ที่คำนึงถึงรูปทรงของห้องและคุณสมบัติการสะท้อนแสงของผนัง เพดาน และพื้น รวมถึงตัวประกอบการบำรุงรักษา (Maintenance Factor) ที่คำนึงถึงการเสื่อมสภาพของหลอดไฟและความสกปรกที่สะสมตามเวลา', 'วิธีนี้เหมาะสำหรับการคำนวณค่าความส่องสว่างเฉลี่ยในพื้นที่ที่มีรูปทรงสม่ำเสมอและต้องการแสงสว่างที่กระจายทั่วถึง เช่น สำนักงานหรือห้องเรียน แต่มีข้อจำกัดในการแสดงการกระจายแสงเฉพาะจุดที่ละเอียด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วิธีคำนวณแสงสว่างแบบ Lumen Method (หรือ Zonal Cavity Method) ใช้หลักการพื้นฐานอย่างไรในการหาจำนวนโคมไฟที่ต้องติดตั้ง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วิธีคำนวณแสงสว่างแบบ Point-by-Point Method แตกต่างจาก Lumen Method อย่างไร และเหมาะกับการใช้งานลักษณะใด', 'วิธีนี้คำนวณค่าความส่องสว่างที่จุดใดจุดหนึ่งโดยเฉพาะบนพื้นที่เป้าหมาย โดยพิจารณาระยะทางและมุมจากแต่ละดวงโคมไฟไปยังจุดนั้น ให้ผลลัพธ์ที่ละเอียดและแม่นยำกว่า Lumen Method ที่ให้เพียงค่าเฉลี่ยของพื้นที่ทั้งหมด', 'วิธีนี้เหมาะกับการออกแบบที่ต้องการทราบการกระจายแสงเฉพาะจุดอย่างละเอียด เช่น ระบบแสงสว่างสนามกีฬาหรือทางหลวง ที่ค่าความส่องสว่างต้องสม่ำเสมอในแต่ละตำแหน่งตามมาตรฐานที่กำหนด แต่ต้องใช้การคำนวณที่ซับซ้อนกว่ามาก มักอาศัยโปรแกรมคอมพิวเตอร์ช่วยคำนวณ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วิธีคำนวณแสงสว่างแบบ Point-by-Point Method แตกต่างจาก Lumen Method อย่างไร และเหมาะกับการใช้งานลักษณะใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ตัวประกอบการบำรุงรักษา (Maintenance Factor หรือ Light Loss Factor) ในการออกแบบระบบแสงสว่างมีความสำคัญอย่างไร', 'เป็นตัวคูณที่คำนึงถึงการลดลงของปริมาณแสงตามเวลา จากปัจจัยต่างๆ เช่น การเสื่อมสภาพของหลอดไฟ ฝุ่นละอองสะสมบนโคมไฟและผนัง และการเปลี่ยนแปลงคุณสมบัติการสะท้อนแสงของห้องตามอายุการใช้งาน การออกแบบที่ไม่พิจารณาตัวประกอบนี้จะทำให้ระบบแสงสว่างมีความส่องสว่างต่ำกว่าเป้าหมายเมื่อผ่านการใช้งานไประยะหนึ่ง', 'การออกแบบที่ดีจึงมักเผื่อปริมาณแสงเริ่มต้นให้สูงกว่าค่าเป้าหมายที่ต้องการ เพื่อให้เมื่อผ่านช่วงเวลาการเสื่อมสภาพตามที่คาดการณ์ไว้แล้ว ค่าความส่องสว่างยังคงอยู่ในเกณฑ์ที่ยอมรับได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ตัวประกอบการบำรุงรักษา (Maintenance Factor หรือ Light Loss Factor) ในการออกแบบระบบแสงสว่างมีความสำคัญอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'โคมไฟแบบ Direct, Indirect และ Direct-Indirect แตกต่างกันอย่างไรในลักษณะการกระจายแสง', 'โคมไฟแบบ Direct ส่งแสงส่วนใหญ่ลงตรงไปยังพื้นที่ทำงานโดยตรง ให้ประสิทธิภาพการใช้แสงสูงแต่อาจมีปัญหาแสงจ้าบาดตาได้ง่ายกว่า โคมไฟแบบ Indirect ส่งแสงขึ้นไปสะท้อนกับเพดานก่อนกระจายลงมา ให้แสงที่นุ่มนวลและลดแสงจ้าได้ดีแต่มีประสิทธิภาพต่ำกว่า ส่วนแบบ Direct-Indirect ผสมผสานทั้งสองลักษณะเพื่อสมดุลระหว่างประสิทธิภาพและความสบายตา', 'การเลือกลักษณะการกระจายแสงที่เหมาะสมขึ้นอยู่กับลักษณะงานและความสูงของเพดาน เช่น พื้นที่สำนักงานที่ใช้คอมพิวเตอร์มากมักนิยมใช้แบบ Indirect หรือ Direct-Indirect เพื่อลดแสงสะท้อนบนหน้าจอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'โคมไฟแบบ Direct, Indirect และ Direct-Indirect แตกต่างกันอย่างไรในลักษณะการกระจายแสง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบแสงสว่างฉุกเฉิน (Emergency Lighting) ในอาคารต้องออกแบบให้มีค่าความส่องสว่างขั้นต่ำอย่างไรตามหลักการความปลอดภัยทั่วไป', 'โดยทั่วไปต้องออกแบบให้มีค่าความส่องสว่างขั้นต่ำเพียงพอสำหรับให้ผู้ใช้อาคารมองเห็นเส้นทางหนีไฟและสิ่งกีดขวางได้อย่างปลอดภัย แม้จะต่ำกว่าค่าความส่องสว่างปกติมาก โดยต้องคงระดับความสว่างนี้ได้เป็นระยะเวลาขั้นต่ำที่กำหนด (มักอย่างน้อย 90 นาที) นับจากไฟฟ้าปกติดับ เพื่อให้เพียงพอต่อการอพยพออกจากอาคาร', 'ระบบแสงสว่างฉุกเฉินมักใช้แบตเตอรี่สำรองในตัวโคมไฟเอง (Self-contained) หรือเชื่อมต่อกับระบบไฟฟ้าสำรองส่วนกลางของอาคาร ขึ้นอยู่กับการออกแบบและขนาดของอาคารนั้นๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบแสงสว่างฉุกเฉิน (Emergency Lighting) ในอาคารต้องออกแบบให้มีค่าความส่องสว่างขั้นต่ำอย่างไรตามหลักการความปลอดภัยทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ป้ายทางออกฉุกเฉิน (Exit Sign) ที่มีไฟส่องสว่างในตัว ต้องออกแบบให้มองเห็นได้ชัดเจนในสภาวะใดบ้าง', 'ต้องมองเห็นได้ชัดเจนทั้งในสภาวะไฟฟ้าปกติทำงานอยู่และในสภาวะฉุกเฉินที่ไฟฟ้าหลักดับ โดยอาศัยแบตเตอรี่สำรองภายในตัวป้ายหรือเชื่อมต่อกับระบบไฟฟ้าฉุกเฉินของอาคาร เพื่อให้ผู้ใช้อาคารสามารถระบุทิศทางไปยังทางออกได้ตลอดเวลาแม้ในสภาวะฉุกเฉินที่มีควันหรือแสงสว่างจำกัด', 'ตำแหน่งการติดตั้งป้ายทางออกฉุกเฉินต้องวางแผนให้ผู้ใช้อาคารสามารถมองเห็นป้ายถัดไปได้จากทุกจุดตลอดเส้นทางหนีไฟ ไม่มีช่วงที่มองไม่เห็นป้ายใดๆ เลย เพื่อไม่ให้เกิดความสับสนในการอพยพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ป้ายทางออกฉุกเฉิน (Exit Sign) ที่มีไฟส่องสว่างในตัว ต้องออกแบบให้มองเห็นได้ชัดเจนในสภาวะใดบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบระบบแสงสว่างถนน (Road Lighting) ต้องพิจารณาความสม่ำเสมอของแสง (Uniformity) นอกเหนือจากค่าความส่องสว่างเฉลี่ย เพราะเหตุใด', 'เพราะความสม่ำเสมอของแสงที่ไม่ดี แม้ค่าเฉลี่ยจะสูงเพียงพอ อาจทำให้เกิดจุดมืดสลับจุดสว่างตลอดเส้นทาง ซึ่งรบกวนการปรับตัวของสายตาผู้ขับขี่ในการมองเห็นสิ่งกีดขวางหรืออันตรายบนถนน โดยเฉพาะช่วงเปลี่ยนผ่านระหว่างพื้นที่สว่างและมืดที่กะทันหันเกินไป', 'มาตรฐานการออกแบบแสงสว่างถนนจึงมักกำหนดทั้งค่าความส่องสว่างเฉลี่ยขั้นต่ำและอัตราส่วนความสม่ำเสมอ (เช่น อัตราส่วนระหว่างค่าต่ำสุดต่อค่าเฉลี่ย) เพื่อให้มั่นใจว่าแสงสว่างตลอดเส้นทางมีความต่อเนื่องและปลอดภัยสำหรับการขับขี่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบระบบแสงสว่างถนน (Road Lighting) ต้องพิจารณาความสม่ำเสมอของแสง (Uniformity) นอกเหนือจากค่าความส่องสว่างเฉลี่ย เพราะเหตุใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบแสงสว่างสำหรับสนามกีฬา (Sports Lighting) มีข้อกำหนดพิเศษที่แตกต่างจากแสงสว่างทั่วไปอย่างไร', 'ต้องพิจารณาค่าความส่องสว่างที่สูงกว่าพื้นที่ทั่วไปมาก และต้องควบคุมแสงจ้าที่อาจรบกวนสายตาผู้เล่นหรือกล้องถ่ายทอดสด รวมถึงต้องพิจารณาอัตราส่วนความส่องสว่างแนวตั้ง (Vertical Illuminance) สำหรับกีฬาบางประเภทที่ต้องมองวัตถุในแนวสูง เช่น การเสิร์ฟลูกในกีฬาวอลเลย์บอลหรือเทนนิส', 'ระดับความส่องสว่างที่ต้องการยังแปรผันตามระดับการแข่งขัน เช่น การแข่งขันระดับนานาชาติที่มีการถ่ายทอดโทรทัศน์ความละเอียดสูงต้องการค่าความส่องสว่างและคุณภาพของแสงที่สูงกว่าสนามฝึกซ้อมทั่วไปมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบแสงสว่างสำหรับสนามกีฬา (Sports Lighting) มีข้อกำหนดพิเศษที่แตกต่างจากแสงสว่างทั่วไปอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบควบคุมแสงสว่างแบบ DALI (Digital Addressable Lighting Interface) มีข้อดีอย่างไรเหนือกว่าระบบควบคุมแบบเปิดปิดธรรมดา', 'DALI เป็นโปรโตคอลการสื่อสารดิจิทัลที่ช่วยให้สามารถควบคุมโคมไฟแต่ละดวงหรือแต่ละกลุ่มได้อย่างอิสระผ่านระบบเดียวกัน รวมถึงสามารถหรี่แสง (Dimming) ปรับตั้งค่าฉาก (Scene) และรับข้อมูลสถานะย้อนกลับจากโคมไฟแต่ละดวง เช่น อายุการใช้งานหรือความผิดปกติ ซึ่งระบบเปิดปิดธรรมดาไม่สามารถทำได้', 'ระบบ DALI นิยมใช้ในอาคารขนาดใหญ่ที่ต้องการความยืดหยุ่นในการควบคุมแสงสว่างสูง เช่น สามารถปรับฉากแสงให้เหมาะกับการใช้งานที่แตกต่างกันในห้องเดียวกัน หรือติดตามสถานะของโคมไฟจำนวนมากจากศูนย์กลางเพื่อการบำรุงรักษาที่มีประสิทธิภาพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบควบคุมแสงสว่างแบบ DALI (Digital Addressable Lighting Interface) มีข้อดีอย่างไรเหนือกว่าระบบควบคุมแบบเปิดปิดธรรมดา'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มลภาวะทางแสง (Light Pollution) จากระบบแสงสว่างกลางแจ้งคืออะไร และมีผลกระทบอย่างไร', 'คือแสงสว่างที่ฟุ้งกระจายออกไปในทิศทางที่ไม่จำเป็นหรือไม่ต้องการ เช่น แสงที่ส่องขึ้นสู่ท้องฟ้าโดยไม่มีประโยชน์ หรือแสงที่รุกล้ำเข้าไปในพื้นที่ข้างเคียงที่ไม่ต้องการแสงสว่าง ผลกระทบรวมถึงการรบกวนการสังเกตดาราศาสตร์ ผลกระทบต่อระบบนิเวศของสัตว์กลางคืน และความรำคาญต่อผู้อยู่อาศัยใกล้เคียง', 'การออกแบบโคมไฟที่มีคุณภาพดีมักมีแผ่นบังแสงหรือรูปทรงที่ควบคุมทิศทางแสงให้ส่องเฉพาะพื้นที่เป้าหมาย ลดแสงที่ฟุ้งกระจายขึ้นสู่ท้องฟ้าหรือรุกล้ำพื้นที่ข้างเคียงโดยไม่จำเป็น ซึ่งช่วยลดมลภาวะทางแสงและยังประหยัดพลังงานไปพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มลภาวะทางแสง (Light Pollution) จากระบบแสงสว่างกลางแจ้งคืออะไร และมีผลกระทบอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบแสงสว่างในโรงงานอุตสาหกรรมที่มีเครื่องจักรหมุน จึงต้องระวังปรากฏการณ์สโตรโบสโคปิก (Stroboscopic Effect)', 'เพราะแหล่งกำเนิดแสงบางชนิดมีความสว่างที่กระพริบตามความถี่ของแหล่งจ่ายไฟฟ้ากระแสสลับ หากความถี่การกระพริบนี้ใกล้เคียงหรือเป็นจำนวนเท่าของความเร็วรอบการหมุนของเครื่องจักร อาจทำให้มองเห็นชิ้นส่วนที่หมุนอยู่ดูเหมือนหยุดนิ่งหรือเคลื่อนที่ช้าผิดปกติ ซึ่งเป็นอันตรายอย่างยิ่งต่อผู้ปฏิบัติงานที่อาจเข้าใจผิดว่าเครื่องจักรหยุดทำงานแล้ว', 'การป้องกันปรากฏการณ์นี้ทำได้หลายวิธี เช่น การใช้บัลลาสต์อิเล็กทรอนิกส์ความถี่สูงแทนบัลลาสต์แม่เหล็กไฟฟ้าความถี่ปกติ หรือการจัดวางโคมไฟหลายดวงให้เฟสไฟฟ้าต่างกันเพื่อลดผลกระทบของการกระพริบพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบแสงสว่างในโรงงานอุตสาหกรรมที่มีเครื่องจักรหมุน จึงต้องระวังปรากฏการณ์สโตรโบสโคปิก (Stroboscopic Effect)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบแสงสว่างสำหรับพื้นที่ที่มีความเสี่ยงด้านความปลอดภัยสูง เช่น บันไดหรือทางเดินต่างระดับ ต้องพิจารณาปัจจัยพิเศษอะไรเพิ่มเติมจากค่าความส่องสว่างทั่วไป', 'ต้องพิจารณาการส่องแสงให้เห็นขอบและระดับความสูงของแต่ละขั้นบันไดหรือจุดต่างระดับได้อย่างชัดเจน เพื่อป้องกันการสะดุดหรือพลัดตกจากความไม่แน่ใจในตำแหน่งของขั้นบันได รวมถึงหลีกเลี่ยงเงาที่อาจบดบังขอบของขั้นบันไดจากมุมการติดตั้งโคมไฟที่ไม่เหมาะสม', 'การออกแบบที่ดีมักติดตั้งไฟส่องเฉพาะบริเวณขอบขั้นบันไดหรือใช้แสงที่มีทิศทางเหมาะสมเพื่อสร้างเงาที่ช่วยเน้นให้เห็นขอบขั้นบันไดชัดเจนขึ้น แทนที่จะให้แสงราบเรียบสม่ำเสมอเพียงอย่างเดียวซึ่งอาจทำให้มองไม่เห็นความแตกต่างของระดับได้ชัดเจนพอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบแสงสว่างสำหรับพื้นที่ที่มีความเสี่ยงด้านความปลอดภัยสูง เช่น บันไดหรือทางเดินต่างระดับ ต้องพิจารณาปัจจัยพิเศษอะไรเพิ่มเติมจากค่าความส่องสว่างทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดพื้นที่ทำงานที่ต้องใช้จอคอมพิวเตอร์เป็นเวลานาน จึงต้องออกแบบระบบแสงสว่างให้พิจารณาแสงสะท้อนบนหน้าจอ (Screen Reflection) เป็นพิเศษ', 'เพราะแสงสะท้อนที่เกิดขึ้นบนหน้าจอคอมพิวเตอร์ทำให้ผู้ใช้งานต้องเพ่งมองผ่านแสงสะท้อนเพื่ออ่านข้อมูลบนหน้าจอ ซึ่งก่อให้เกิดความเมื่อยล้าทางสายตาและอาจนำไปสู่ปัญหาสุขภาพตาในระยะยาวหากต้องเผชิญกับสภาวะนี้เป็นเวลานานทุกวัน', 'การแก้ไขปัญหานี้ทำได้หลายวิธี เช่น การจัดตำแหน่งโคมไฟให้ไม่อยู่ในตำแหน่งที่สะท้อนเข้าตาผู้ใช้งานโดยตรง การเลือกใช้โคมไฟที่มีความสว่างจำกัดในมุมต่ำ (Low Glare Luminaire) หรือการจัดวางตำแหน่งจอคอมพิวเตอร์และโต๊ะทำงานให้เหมาะสมกับทิศทางแสง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดพื้นที่ทำงานที่ต้องใช้จอคอมพิวเตอร์เป็นเวลานาน จึงต้องออกแบบระบบแสงสว่างให้พิจารณาแสงสะท้อนบนหน้าจอ (Screen Reflection) เป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'หลอดไฟที่มีแสงกระพริบ (Flicker) แม้ตาเปล่ามองไม่เห็นความกระพริบนั้น ยังคงส่งผลเสียต่อสุขภาพได้หรือไม่ เพราะเหตุใด', 'ยังคงส่งผลเสียได้ เพราะแม้ความถี่การกระพริบจะสูงเกินกว่าที่ตาเปล่าจะรับรู้ได้โดยตรง (Perceptible Flicker) แต่ในบางความถี่อาจยังคงส่งผลกระทบทางสรีรวิทยาโดยไม่รู้ตัว เช่น อาการปวดหัว เมื่อยล้าทางสายตา หรือในบางกรณีอาจกระตุ้นอาการชักในผู้ที่มีความไวต่อแสงกระพริบเป็นพิเศษ', 'มาตรฐานการออกแบบระบบแสงสว่างสมัยใหม่จึงเริ่มกำหนดเกณฑ์ด้านคุณภาพแสงกระพริบ (Flicker Metrics) เพิ่มเติมนอกเหนือจากค่าความส่องสว่างพื้นฐาน โดยเฉพาะสำหรับหลอดไฟ LED ที่ควบคุมความสว่างด้วยวงจรอิเล็กทรอนิกส์ซึ่งอาจมีความเสี่ยงจากปัญหานี้หากออกแบบวงจรขับหลอดไม่ดีพอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'หลอดไฟที่มีแสงกระพริบ (Flicker) แม้ตาเปล่ามองไม่เห็นความกระพริบนั้น ยังคงส่งผลเสียต่อสุขภาพได้หรือไม่ เพราะเหตุใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกดัชนีป้องกันฝุ่นและน้ำ (Ingress Protection, IP Rating) ของโคมไฟจึงต้องเหมาะสมกับสภาพแวดล้อมการติดตั้ง', 'เพราะโคมไฟที่ติดตั้งในสภาพแวดล้อมที่แตกต่างกันต้องเผชิญกับความเสี่ยงจากฝุ่น ความชื้น หรือน้ำที่แตกต่างกัน โคมไฟที่มีค่า IP Rating ไม่เพียงพอต่อสภาพแวดล้อมที่ติดตั้งจริง อาจเกิดความเสียหายจากฝุ่นหรือน้ำที่เข้าไปสัมผัสกับวงจรไฟฟ้าภายใน ซึ่งอาจนำไปสู่ความล้มเหลวก่อนเวลาอันควรหรือเป็นอันตรายจากไฟฟ้าลัดวงจร', 'ตัวอย่างเช่น โคมไฟที่ติดตั้งกลางแจ้งหรือในพื้นที่ที่มีการฉีดล้างทำความสะอาดบ่อย เช่น โรงงานอาหาร ต้องเลือกค่า IP Rating ที่สูงกว่าโคมไฟที่ติดตั้งภายในสำนักงานทั่วไปที่มีสภาพแวดล้อมควบคุมได้ดีกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกดัชนีป้องกันฝุ่นและน้ำ (Ingress Protection, IP Rating) ของโคมไฟจึงต้องเหมาะสมกับสภาพแวดล้อมการติดตั้ง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบแสงสว่างในพื้นที่ที่มีความเสี่ยงจากบรรยากาศไวไฟ จึงต้องเลือกใช้โคมไฟชนิดกันระเบิด (Explosion Proof Luminaire) เช่นเดียวกับอุปกรณ์ไฟฟ้าอื่นในพื้นที่นั้น', 'เพราะหลอดไฟและวงจรไฟฟ้าภายในโคมไฟทั่วไปอาจเกิดความร้อนสูงหรือประกายไฟขณะสตาร์ทหรือขณะทำงานปกติ ซึ่งอาจเป็นแหล่งจุดระเบิดของไอระเหยไวไฟในบรรยากาศได้เช่นเดียวกับอุปกรณ์ไฟฟ้าประเภทอื่น จึงต้องใช้โคมไฟที่ออกแบบพิเศษให้ปิดผนึกป้องกันไม่ให้ประกายไฟหรือความร้อนภายในลุกลามออกสู่บรรยากาศภายนอกได้', 'การเลือกใช้โคมไฟที่เหมาะสมกับการจำแนกพื้นที่เสี่ยงอันตราย (Area Classification) เป็นข้อกำหนดสำคัญเช่นเดียวกับที่กล่าวถึงในการเลือกอุปกรณ์ไฟฟ้าประเภทอื่นสำหรับพื้นที่เสี่ยงอันตราย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบแสงสว่างในพื้นที่ที่มีความเสี่ยงจากบรรยากาศไวไฟ จึงต้องเลือกใช้โคมไฟชนิดกันระเบิด (Explosion Proof Luminaire) เช่นเดียวกับอุปกรณ์ไฟฟ้าอื่นในพื้นที่นั้น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบแสงสว่างในโรงพยาบาลหรือสถานพยาบาล จึงต้องพิจารณาความแตกต่างของข้อกำหนดระหว่างพื้นที่ตรวจรักษาและพื้นที่พักผู้ป่วย', 'พื้นที่ตรวจรักษา เช่น ห้องผ่าตัดหรือห้องตรวจ ต้องการความส่องสว่างสูงมากและค่า CRI สูงเพื่อให้บุคลากรทางการแพทย์มองเห็นรายละเอียดได้ชัดเจนแม่นยำ ในขณะที่พื้นที่พักผู้ป่วยควรมีแสงสว่างที่นุ่มนวลกว่าเพื่อส่งเสริมการพักผ่อนและฟื้นตัว รวมถึงมักต้องมีระบบควบคุมแสงที่ปรับได้ตามความต้องการของผู้ป่วยแต่ละราย', 'การออกแบบแสงสว่างในสถานพยาบาลจึงมีความซับซ้อนมากกว่าอาคารทั่วไป เนื่องจากต้องสมดุลระหว่างความต้องการทางการแพทย์ที่เข้มงวดในบางพื้นที่ กับความสบายและการฟื้นตัวของผู้ป่วยในพื้นที่อื่น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบแสงสว่างในโรงพยาบาลหรือสถานพยาบาล จึงต้องพิจารณาความแตกต่างของข้อกำหนดระหว่างพื้นที่ตรวจรักษาและพื้นที่พักผู้ป่วย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกใช้ระบบแสงสว่างที่ปรับอุณหภูมิสีได้ตามช่วงเวลา (Tunable White หรือ Human Centric Lighting) จึงได้รับความสนใจเพิ่มขึ้นในการออกแบบอาคารสมัยใหม่', 'เพราะแนวคิดนี้อาศัยความเข้าใจเกี่ยวกับผลกระทบของแสงต่อจังหวะชีวภาพ (Circadian Rhythm) ของมนุษย์ โดยปรับอุณหภูมิสีของแสงให้ใกล้เคียงกับแสงธรรมชาติในแต่ละช่วงเวลาของวัน เช่น แสงโทนเย็นและสว่างในช่วงเช้าเพื่อกระตุ้นความตื่นตัว และแสงโทนอุ่นในช่วงเย็นเพื่อส่งเสริมการพักผ่อน', 'เทคโนโลยีนี้เริ่มถูกนำไปใช้ในสถานที่ที่ผู้ใช้งานอยู่เป็นเวลานาน เช่น สำนักงาน โรงเรียน หรือสถานพยาบาล เพื่อส่งเสริมสุขภาวะและประสิทธิภาพการทำงานของผู้ใช้อาคาร แม้จะมีต้นทุนสูงกว่าระบบแสงสว่างทั่วไปที่มีอุณหภูมิสีคงที่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกใช้ระบบแสงสว่างที่ปรับอุณหภูมิสีได้ตามช่วงเวลา (Tunable White หรือ Human Centric Lighting) จึงได้รับความสนใจเพิ่มขึ้นในการออกแบบอาคารสมัยใหม่'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการคำนวณค่าความส่องสว่างในพื้นที่ที่มีชั้นวางสินค้าสูงในคลังสินค้า จึงต้องพิจารณาแสงเงาที่เกิดจากชั้นวางเป็นพิเศษ', 'เพราะชั้นวางสินค้าที่สูงและตั้งเรียงกันหนาแน่นอาจบดบังแสงจากโคมไฟที่ติดตั้งบนเพดาน ทำให้บริเวณช่องทางเดินระหว่างชั้นวางหรือชั้นวางระดับล่างได้รับแสงไม่เพียงพอ แม้ค่าความส่องสว่างเฉลี่ยของทั้งพื้นที่จะดูเพียงพอตามการคำนวณแบบภาพรวมก็ตาม', 'การออกแบบที่ดีจึงมักต้องพิจารณาตำแหน่งโคมไฟให้สอดคล้องกับแนวช่องทางเดินระหว่างชั้นวาง หรือติดตั้งโคมไฟเพิ่มเติมเฉพาะจุดในบริเวณที่มีความเสี่ยงจากเงาบัง แทนที่จะกระจายโคมไฟสม่ำเสมอทั่วเพดานโดยไม่คำนึงถึงตำแหน่งของชั้นวางสินค้า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการคำนวณค่าความส่องสว่างในพื้นที่ที่มีชั้นวางสินค้าสูงในคลังสินค้า จึงต้องพิจารณาแสงเงาที่เกิดจากชั้นวางเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบระบบแสงสว่างอาคารประหยัดพลังงาน จึงมักกำหนดค่ากำลังไฟฟ้าส่องสว่างต่อพื้นที่ (Lighting Power Density, LPD) เป็นเกณฑ์ควบคุมเพิ่มเติมจากค่าความส่องสว่างที่ต้องการ', 'เพราะเพียงกำหนดค่าความส่องสว่างเป้าหมายอย่างเดียวไม่ได้รับประกันว่าระบบจะมีประสิทธิภาพการใช้พลังงานที่ดี เนื่องจากสามารถบรรลุค่าความส่องสว่างเดียวกันได้ด้วยวิธีที่ใช้พลังงานมากหรือน้อยแตกต่างกันมาก ค่า LPD จึงเป็นเกณฑ์เพิ่มเติมที่บังคับให้ผู้ออกแบบต้องเลือกใช้เทคโนโลยีและวิธีการที่มีประสิทธิภาพเพื่อให้ได้ความส่องสว่างตามต้องการโดยใช้กำลังไฟฟ้าไม่เกินขีดจำกัดที่กำหนด', 'มาตรฐานอาคารประหยัดพลังงานหลายประเทศกำหนดค่า LPD สูงสุดที่ยอมรับได้แตกต่างกันตามประเภทการใช้งานพื้นที่ เพื่อผลักดันให้อุตสาหกรรมออกแบบและก่อสร้างมุ่งสู่ระบบแสงสว่างที่มีประสิทธิภาพสูงขึ้นอย่างต่อเนื่อง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบระบบแสงสว่างอาคารประหยัดพลังงาน จึงมักกำหนดค่ากำลังไฟฟ้าส่องสว่างต่อพื้นที่ (Lighting Power Density, LPD) เป็นเกณฑ์ควบคุมเพิ่มเติมจากค่าความส่องสว่างที่ต้องการ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกตำแหน่งติดตั้งเซนเซอร์แสงสำหรับระบบ Daylight Harvesting จึงมีผลอย่างมากต่อประสิทธิภาพของระบบ', 'เพราะเซนเซอร์แสงต้องตรวจวัดระดับแสงในตำแหน่งที่เป็นตัวแทนที่ดีของพื้นที่ทำงานจริง หากติดตั้งใกล้หน้าต่างมากเกินไป อาจตรวจวัดค่าแสงที่สูงเกินความเป็นจริงของพื้นที่ทำงานส่วนใหญ่ ทำให้ระบบหรี่ไฟฟ้ามากเกินไปจนพื้นที่ทำงานจริงได้รับแสงไม่เพียงพอ ในทางกลับกันหากติดตั้งไกลจากหน้าต่างเกินไป อาจไม่ตรวจจับการเปลี่ยนแปลงของแสงธรรมชาติได้อย่างมีประสิทธิภาพ', 'การปรับเทียบ (Calibration) เซนเซอร์แสงหลังการติดตั้งจึงเป็นขั้นตอนสำคัญที่ต้องทำอย่างระมัดระวัง เพื่อให้ระบบทำงานสอดคล้องกับความต้องการแสงสว่างจริงของพื้นที่ทำงาน ไม่ใช่เพียงติดตั้งเซนเซอร์แล้วถือว่าระบบพร้อมใช้งานทันที', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกตำแหน่งติดตั้งเซนเซอร์แสงสำหรับระบบ Daylight Harvesting จึงมีผลอย่างมากต่อประสิทธิภาพของระบบ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบแสงสว่างสำหรับงานศิลปะหรือพิพิธภัณฑ์ จึงต้องพิจารณาผลกระทบของแสงต่อการเสื่อมสภาพของวัตถุจัดแสดง นอกเหนือจากคุณภาพการมองเห็น', 'เพราะพลังงานแสง โดยเฉพาะรังสียูวีและอินฟราเรดที่มากับแสงบางประเภท สามารถเร่งการเสื่อมสภาพของวัสดุที่ไวต่อแสง เช่น สีย้อมในภาพวาดหรือเส้นใยธรรมชาติในสิ่งทอโบราณ การออกแบบแสงสว่างสำหรับพิพิธภัณฑ์จึงต้องจำกัดปริมาณรังสีที่เป็นอันตรายเหล่านี้ ควบคู่ไปกับการให้แสงสว่างที่เพียงพอสำหรับการชมงานศิลปะ', 'การเลือกใช้แหล่งกำเนิดแสงที่มีการปล่อยรังสียูวีต่ำ พร้อมกับการควบคุมระยะเวลาที่วัตถุจัดแสดงได้รับแสง เป็นแนวทางสำคัญในการรักษาสภาพของวัตถุจัดแสดงที่มีคุณค่าทางประวัติศาสตร์หรือศิลปะให้คงอยู่ได้ยาวนานที่สุด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบแสงสว่างสำหรับงานศิลปะหรือพิพิธภัณฑ์ จึงต้องพิจารณาผลกระทบของแสงต่อการเสื่อมสภาพของวัตถุจัดแสดง นอกเหนือจากคุณภาพการมองเห็น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการทดสอบและปรับตั้งระบบแสงสว่าง (Lighting Commissioning) หลังการติดตั้งจึงมีความสำคัญ แม้จะออกแบบตามการคำนวณอย่างละเอียดแล้วก็ตาม', 'เพราะการติดตั้งจริงอาจมีความคลาดเคลื่อนจากแบบที่คำนวณไว้ เช่น ตำแหน่งโคมไฟที่ต้องปรับเปลี่ยนเนื่องจากข้อจำกัดหน้างาน หรือคุณสมบัติการสะท้อนแสงของวัสดุตกแต่งจริงที่แตกต่างจากค่าที่สมมติไว้ในการคำนวณ การตรวจวัดค่าความส่องสว่างจริงหลังการติดตั้งช่วยยืนยันว่าระบบทำงานตรงตามเป้าหมายที่ออกแบบไว้จริง', 'หากพบว่าค่าความส่องสว่างจริงไม่ตรงตามเป้าหมาย อาจต้องปรับตั้งค่าระบบควบคุม เปลี่ยนตำแหน่งโคมไฟบางจุด หรือในบางกรณีต้องเพิ่มโคมไฟเสริมเพื่อให้บรรลุเป้าหมายที่กำหนดไว้ตั้งแต่ขั้นตอนออกแบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการทดสอบและปรับตั้งระบบแสงสว่าง (Lighting Commissioning) หลังการติดตั้งจึงมีความสำคัญ แม้จะออกแบบตามการคำนวณอย่างละเอียดแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดค่าความส่องสว่างที่เหมาะสมสำหรับผู้สูงอายุจึงมักต้องการสูงกว่าค่าที่แนะนำสำหรับคนทั่วไปในการทำงานลักษณะเดียวกัน', 'เพราะความสามารถในการรับแสงของดวงตาลดลงตามอายุ เนื่องจากการเปลี่ยนแปลงทางสรีรวิทยาของเลนส์ตาและม่านตาที่ทำให้แสงเข้าสู่จอประสาทตาได้น้อยลง ผู้สูงอายุจึงต้องการปริมาณแสงที่มากขึ้นเพื่อให้มองเห็นรายละเอียดได้ชัดเจนเทียบเท่ากับที่คนอายุน้อยกว่ามองเห็นได้ที่ค่าความส่องสว่างต่ำกว่า', 'การออกแบบแสงสว่างในพื้นที่ที่มีผู้ใช้งานเป็นผู้สูงอายุเป็นหลัก เช่น สถานพยาบาลผู้สูงอายุหรือบ้านพักคนชรา จึงควรพิจารณาเพิ่มค่าความส่องสว่างเป้าหมายให้สูงกว่ามาตรฐานทั่วไปที่ออกแบบสำหรับประชากรทั่วไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดค่าความส่องสว่างที่เหมาะสมสำหรับผู้สูงอายุจึงมักต้องการสูงกว่าค่าที่แนะนำสำหรับคนทั่วไปในการทำงานลักษณะเดียวกัน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบแสงสว่างสำหรับป้ายโฆษณาหรือป้ายร้านค้าภายนอกอาคาร จึงต้องพิจารณาข้อกำหนดด้านผังเมืองและกฎหมายควบคุมอาคารร่วมด้วย', 'เพราะแสงสว่างจากป้ายที่มีความสว่างมากเกินไปหรือมีลักษณะกระพริบ อาจก่อให้เกิดความรำคาญหรืออันตรายต่อผู้ใช้ถนนใกล้เคียง โดยเฉพาะหากตำแหน่งติดตั้งอยู่ใกล้ทางแยกที่อาจรบกวนการมองเห็นสัญญาณไฟจราจร หลายพื้นที่จึงมีข้อกำหนดเฉพาะเกี่ยวกับความสว่างสูงสุด ลักษณะการกระพริบ และตำแหน่งการติดตั้งป้ายที่มีไฟส่องสว่างในพื้นที่สาธารณะ', 'ผู้ออกแบบจึงต้องตรวจสอบข้อกำหนดท้องถิ่นที่เกี่ยวข้องก่อนออกแบบป้ายที่มีไฟส่องสว่าง เพื่อให้สอดคล้องกับกฎหมายและไม่ก่อให้เกิดผลกระทบต่อความปลอดภัยสาธารณะ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบแสงสว่างสำหรับป้ายโฆษณาหรือป้ายร้านค้าภายนอกอาคาร จึงต้องพิจารณาข้อกำหนดด้านผังเมืองและกฎหมายควบคุมอาคารร่วมด้วย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบแสงสว่างสำหรับอุโมงค์ (Tunnel Lighting) จึงต้องกำหนดค่าความส่องสว่างที่แตกต่างกันตามช่วงต่างๆ ของอุโมงค์ แทนที่จะใช้ค่าเดียวกันตลอดความยาว', 'เพราะดวงตาของผู้ขับขี่ต้องปรับตัวจากสภาพแสงธรรมชาติภายนอกที่สว่างมาก เข้าสู่สภาพแสงภายในอุโมงค์ที่มืดกว่ามาก ซึ่งใช้เวลาในการปรับตัว หากช่วงทางเข้าอุโมงค์มีความส่องสว่างต่ำเกินไปทันที ผู้ขับขี่อาจมองไม่เห็นสิ่งกีดขวางในช่วงเวลาสั้นๆ ที่ตายังไม่ปรับตัว จึงต้องออกแบบให้มีโซนความส่องสว่างสูงบริเวณทางเข้าแล้วค่อยๆ ลดระดับลงจนถึงค่าปกติภายในอุโมงค์', 'ในทำนองเดียวกัน ช่วงทางออกของอุโมงค์ก็ต้องพิจารณาการปรับตัวของสายตากลับสู่แสงธรรมชาติภายนอกด้วย ทำให้การออกแบบแสงสว่างอุโมงค์มีความซับซ้อนกว่าการออกแบบถนนทั่วไปที่มีสภาพแสงสม่ำเสมอตลอดเส้นทาง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบแสงสว่างสำหรับอุโมงค์ (Tunnel Lighting) จึงต้องกำหนดค่าความส่องสว่างที่แตกต่างกันตามช่วงต่างๆ ของอุโมงค์ แทนที่จะใช้ค่าเดียวกันตลอดความยาว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรออกแบบแสงสว่างจึงควรพิจารณาทั้งด้านปริมาณ (Quantity) และคุณภาพ (Quality) ของแสง แทนที่จะมุ่งเน้นเพียงการบรรลุค่าความส่องสว่างเป้าหมายตามตัวเลขเพียงอย่างเดียว', 'เพราะการมีปริมาณแสงเพียงพอตามตัวเลขไม่ได้รับประกันว่าผู้ใช้งานจะรู้สึกสบายตาหรือมองเห็นได้อย่างมีประสิทธิภาพ ปัจจัยด้านคุณภาพ เช่น ความสม่ำเสมอของแสง การควบคุมแสงจ้าบาดตา ความถูกต้องของสี และทิศทางของเงาที่เกิดขึ้น ล้วนมีผลต่อประสบการณ์การมองเห็นและความสบายของผู้ใช้งานพื้นที่นั้นไม่น้อยไปกว่าปริมาณแสงเพียงอย่างเดียว', 'การออกแบบแสงสว่างที่ดีจึงเป็นการผสมผสานทั้งศาสตร์ด้านวิศวกรรมไฟฟ้าในการคำนวณและควบคุมปริมาณแสง ร่วมกับความเข้าใจด้านการรับรู้ทางสายตาของมนุษย์ เพื่อสร้างสภาพแวดล้อมที่ทั้งมีประสิทธิภาพและสร้างประสบการณ์ที่ดีให้กับผู้ใช้งานพื้นที่นั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรออกแบบแสงสว่างจึงควรพิจารณาทั้งด้านปริมาณ (Quantity) และคุณภาพ (Quality) ของแสง แทนที่จะมุ่งเน้นเพียงการบรรลุค่าความส่องสว่างเป้าหมายตามตัวเลขเพียงอย่างเดียว'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'lighting'
group by c.name_th;
